w('apps/mock-company/lib/session.ts',r'''import {cookies} from 'next/headers';
import {redirect} from 'next/navigation';
import {validSession} from '@opsagent/db/security';
import {query,env} from '@opsagent/db';
export async function authenticated(system:string){return validSession((await cookies()).get('acme_'+system)?.value,system);}
export async function requireSession(system:string){if(!await authenticated(system))redirect(`/${system}/login`);}
export async function chaos(system:string){const [setting]=await query<{value:boolean}>("SELECT value FROM mock_portal.settings WHERE key='chaos'");const enabled=setting?.value||env.OPSAGENT_CHAOS===1;if(!enabled)return false;await new Promise(r=>setTimeout(r,1000+Math.random()*2000));if(Math.random()<.2)throw Error('Temporary company service failure; retry this page.');if(Math.random()<.08)redirect(`/${system}/login?expired=1`);return true;}
''')
w('apps/mock-company/app/actions.ts',r''' 'use server';
import {cookies} from 'next/headers';
import {redirect} from 'next/navigation';
import {revalidatePath} from 'next/cache';
import {z} from 'zod';
import {query} from '@opsagent/db';
import {signSession} from '@opsagent/db/security';
import {requireSession} from '../lib/session';
const systemSchema=z.enum(['portal','erp','mail']);
export async function login(form:FormData){const system=systemSchema.parse(form.get('system'));if(form.get('username')!=='demo'||form.get('password')!=='demo')redirect(`/${system}/login?error=Invalid+credentials`);(await cookies()).set('acme_'+system,signSession(system),{httpOnly:true,sameSite:'strict',secure:false,path:'/'+system,maxAge:3600});redirect('/'+system);}
const date=z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine(s=>!isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s,'Invalid calendar date');
const payableSchema=z.object({vendor:z.string().min(1),number:z.string().min(1).max(100),amount:z.coerce.number().positive().max(100000000),due:date,notes:z.string().max(10000)});
export async function createPayable(form:FormData){await requireSession('erp');const data=payableSchema.safeParse(Object.fromEntries(form));if(!data.success)redirect('/erp/new?error='+encodeURIComponent(data.error.issues.map(i=>i.path.join('.')+': '+i.message).join('; ')));const p=data.data;const found=await query('SELECT id FROM mock_erp.vendors WHERE name=$1',[p.vendor]);if(!found.length)redirect('/erp/new?error=Unknown+vendor');try{await query('INSERT INTO mock_erp.payables(vendor,number,amount,due,notes) VALUES($1,$2,$3,$4,$5)',[p.vendor,p.number,p.amount,p.due,p.notes]);}catch(e){if((e as {code?:string}).code==='23505')redirect('/erp/new?error=Duplicate+vendor+and+invoice+number');throw e;}revalidatePath('/erp');redirect('/erp?created=1');}
export async function updateVendor(form:FormData){await requireSession('erp');const result=z.object({id:z.string().min(1),email:z.string().email(),phone:z.string().min(5).max(40),notes:z.string().min(1).max(10000)}).safeParse(Object.fromEntries(form));if(!result.success)redirect('/erp/vendors/'+String(form.get('id'))+'?error='+encodeURIComponent(result.error.issues.map(i=>i.message).join('; ')));const p=result.data;await query('UPDATE mock_erp.vendors SET email=$1,phone=$2,notes=$3 WHERE id=$4',[p.email,p.phone,p.notes,p.id]);revalidatePath('/erp/vendors');redirect('/erp/vendors?updated=1');}
export async function sendMail(form:FormData){await requireSession('mail');const result=z.object({to:z.string().email(),subject:z.string().min(1).max(200),body:z.string().min(1).max(50000)}).safeParse(Object.fromEntries(form));if(!result.success)redirect('/mail/compose?error='+encodeURIComponent(result.error.issues.map(i=>i.message).join('; ')));const p=result.data;await query('INSERT INTO mock_mail.messages(sender,recipient,subject,body,folder) VALUES($1,$2,$3,$4,$5)',['finance@acme.test',p.to,p.subject,p.body,'sent']);revalidatePath('/mail/sent');redirect('/mail/sent?sent=1');}
''')
w('apps/mock-company/app/[system]/[[...path]]/page.tsx',r'''import {notFound} from 'next/navigation';
import {query} from '@opsagent/db';
import {requireSession,chaos} from '../../../lib/session';
import {login,createPayable,updateVendor,sendMail} from '../../actions';
export const dynamic='force-dynamic';
type Invoice={id:string;vendor:string;number:string;date:string;amount:string;due:string|null};
type Vendor={id:string;name:string;domain:string;email:string;phone:string;notes:string};
type Payable={id:string;vendor:string;number:string;amount:string;due:string;status:string;entered_by:string;notes:string};
type Message={id:string;sender:string;recipient:string;subject:string;body:string;created_at:Date};
export default async function SystemPage({params,searchParams}:{params:Promise<{system:string;path?:string[]}>;searchParams:Promise<Record<string,string|undefined>>}){const {system,path=[]}=await params;const sp=await searchParams;if(!['portal','erp','mail'].includes(system))notFound();const route=path.join('/');
if(route==='login')return <main><h1>{system.toUpperCase()} sign in</h1>{sp.error&&<p role="alert" className="error">{sp.error}</p>}{sp.expired&&<p>Session expired. Sign in again.</p>}<form action={login} data-operation="login"><input type="hidden" name="system" value={system}/><label>Username<input name="username" autoComplete="username" required/></label><label>Password<input name="password" type="password" autoComplete="current-password" required/></label><button>Sign in</button><p>Demo account: demo / demo</p></form></main>;
await requireSession(system);const changed=await chaos(system);const error=sp.error?<p role="alert" className="error">{sp.error}</p>:null;
if(system==='portal'){
if(route){const [p]=await query<Invoice>('SELECT * FROM mock_portal.invoices WHERE id=$1',[route]);if(!p)notFound();return <main><a href="/portal">All invoices</a><h1>{p.number}</h1><dl><dt>Vendor</dt><dd>{p.vendor}</dd><dt>Invoice date</dt><dd>{p.date}</dd><dt>Status</dt><dd>Available</dd></dl><a download href={`/portal/download/${p.id}`}>{changed?'Get document':'Download PDF'}</a></main>;}
const q=sp.q||'',page=Math.max(1,Number(sp.page)||1);const rows=await query<Invoice>('SELECT * FROM mock_portal.invoices WHERE vendor ILIKE $1 OR number ILIKE $1 ORDER BY date DESC,number LIMIT 5 OFFSET $2',['%'+q+'%',(page-1)*5]);const [count]=await query<{count:string}>('SELECT count(*) FROM mock_portal.invoices WHERE vendor ILIKE $1 OR number ILIKE $1',['%'+q+'%']);return <main><h1>Vendor invoices</h1><div className="toolbar"><form method="get"><label>Search<input name="q" defaultValue={q}/></label><button>Search</button></form><span>{count.count} invoices</span></div><table><thead><tr><th>Vendor</th><th>Invoice</th><th>Date</th><th>Status</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td>{p.vendor}</td><td><a href={'/portal/'+p.id}>{p.number}</a></td><td>{p.date}</td><td>Available</td></tr>)}</tbody></table><div className="pagination">{page>1&&<a href={`?q=${encodeURIComponent(q)}&page=${page-1}`}>Previous</a>}<span>Page {page}</span>{page*5<Number(count.count)&&<a href={`?q=${encodeURIComponent(q)}&page=${page+1}`}>Next page</a>}</div></main>;
}
if(system==='erp'){
if(route==='new'){const vendors=await query<Vendor>('SELECT * FROM mock_erp.vendors ORDER BY name');const fields=[<label key="vendor">Vendor<select name="vendor">{vendors.map(v=><option key={v.id} value={v.name}>{v.name}</option>)}</select></label>,<label key="number">Invoice number<input name="number" required/></label>,<label key="amount">Amount INR<input name="amount" type="number" min="0.01" step="0.01" required/></label>,<label key="due">Due date<input name="due" type="date" required/></label>];return <main><a href="/erp">Payables</a><h1>New payable</h1>{error}<form action={createPayable} data-operation="invoice_create">{changed?fields.reverse():fields}<label>Notes<textarea name="notes"/></label><button>{changed?'Record payable':'Create payable'}</button></form></main>;}
if(route.startsWith('vendors/')){const [v]=await query<Vendor>('SELECT * FROM mock_erp.vendors WHERE id=$1',[path[1]]);if(!v)notFound();return <main><a href="/erp/vendors">Vendors</a><h1>Edit {v.name}</h1>{error}<form action={updateVendor} data-operation="vendor_update" data-vendor-domain={v.domain} data-vendor-name={v.name}><input type="hidden" name="id" value={v.id}/><label>Billing email<input name="email" type="email" defaultValue={v.email} required/></label><label>Phone<input name="phone" defaultValue={v.phone} required/></label><label>Notes<textarea name="notes" defaultValue={v.notes} required/></label><button>{changed?'Apply contact changes':'Save vendor'}</button></form></main>;}
if(route==='vendors'){const rows=await query<Vendor>('SELECT * FROM mock_erp.vendors ORDER BY name');return <main><a href="/erp">Payables</a><h1>Vendor directory</h1><table><thead><tr><th>Vendor</th><th>Registered domain</th><th>Billing email</th><th>Phone</th><th>Notes</th><th/></tr></thead><tbody>{rows.map(v=><tr key={v.id} data-record="vendor"><td data-field="name">{v.name}</td><td data-field="domain">{v.domain}</td><td data-field="email">{v.email}</td><td data-field="phone">{v.phone}</td><td data-field="notes">{v.notes}</td><td><a href={'/erp/vendors/'+v.id}>Edit</a></td></tr>)}</tbody></table></main>;}
const rows=await query<Payable>('SELECT * FROM mock_erp.payables ORDER BY due,number');return <main><h1>Accounts payable</h1><div className="toolbar"><a href="/erp/new">New payable</a><a href="/erp/vendors">Vendors</a></div><table><thead><tr><th>Vendor</th><th>Invoice number</th><th>Amount INR</th><th>Due date</th><th>Status</th><th>Entered by</th></tr></thead><tbody>{rows.map(p=><tr key={p.id} data-record="payable"><td data-field="vendor">{p.vendor}</td><td data-field="number">{p.number}</td><td data-field="amount">{p.amount}</td><td data-field="due">{p.due}</td><td data-field="status">{p.status}</td><td>{p.entered_by}</td></tr>)}</tbody></table></main>;
}
if(route==='compose')return <main><a href="/mail">Inbox</a><h1>Compose message</h1>{error}<form action={sendMail} data-operation="mail_send"><label>To<input name="to" type="email" required/></label><label>Subject<input name="subject" required/></label><label>Body<textarea name="body" rows={12} required/></label><button>{changed?'Dispatch message':'Send message'}</button></form></main>;
if(route&&route!=='sent'){const [m]=await query<Message>('SELECT * FROM mock_mail.messages WHERE id=$1',[route]);if(!m)notFound();return <main><a href="/mail">Inbox</a><h1>{m.subject}</h1><article data-record="message"><dl><dt>From</dt><dd data-field="sender">{m.sender}</dd><dt>To</dt><dd data-field="recipient">{m.recipient}</dd><dt>Subject</dt><dd data-field="subject">{m.subject}</dd></dl><pre data-field="body">{m.body}</pre></article></main>;}
const folder=route==='sent'?'sent':'inbox';const rows=await query<Message>('SELECT * FROM mock_mail.messages WHERE folder=$1 ORDER BY created_at DESC',[folder]);return <main><h1>{folder==='sent'?'Sent messages':'Inbox'}</h1><div className="toolbar"><a href="/mail">Inbox</a><a href="/mail/sent">Sent</a><a href="/mail/compose">Compose</a></div><table><thead><tr><th>{folder==='sent'?'To':'From'}</th><th>Subject</th><th>Date</th></tr></thead><tbody>{rows.map(m=><tr key={m.id}><td>{folder==='sent'?m.recipient:m.sender}</td><td><a href={'/mail/'+m.id}>{m.subject}</a></td><td>{new Date(m.created_at).toISOString().slice(0,16)}</td></tr>)}</tbody></table></main>;
}
''')
w('apps/mock-company/app/portal/download/[id]/route.ts',r'''import {authenticated} from '../../../../lib/session';
import {query,projectRoot} from '@opsagent/db';
import {readFile} from 'node:fs/promises';
import {resolve,relative} from 'node:path';
export async function GET(_req:Request,{params}:{params:Promise<{id:string}>}){if(!await authenticated('portal'))return new Response('Sign in required',{status:401});const {id}=await params;const [row]=await query<{pdf:string;number:string}>('SELECT pdf,number FROM mock_portal.invoices WHERE id=$1',[id]);if(!row)return new Response('Not found',{status:404});const base=resolve(projectRoot,'artifacts/seed-pdfs');if(relative(base,resolve(row.pdf)).startsWith('..'))return new Response('Invalid file',{status:403});return new Response(new Uint8Array(await readFile(row.pdf)),{headers:{'Content-Type':'application/pdf','Content-Disposition':`attachment; filename="${row.number.replace(/[^a-z0-9-]/gi,'_')}.pdf"`}});}
''')
w('apps/mock-company/app/error.tsx',r''' 'use client';
export default function ErrorPage({reset}:{reset:()=>void}){return <main><h1>Temporary service failure</h1><p>The company system could not serve this page. Your submitted data has not been confirmed.</p><button onClick={reset}>Try again</button></main>}
''')
w('apps/mock-company/app/page.tsx',r'''export default function Home(){return <main><h1>Acme company systems</h1><p>Choose a system. Each uses its own session and login.</p><ul><li><a href="/portal">Vendor Portal</a></li><li><a href="/erp">ERP</a></li><li><a href="/mail">Mail</a></li></ul></main>}
''')
